-- ============================================
-- 植物专题扩容：导入水果/干果物种并标记植物属性
-- ============================================

ALTER TABLE public.species
  ADD COLUMN IF NOT EXISTS life_form TEXT,
  ADD COLUMN IF NOT EXISTS cultivation_status TEXT,
  ADD COLUMN IF NOT EXISTS plant_uses TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];

ALTER TABLE public.species
  DROP CONSTRAINT IF EXISTS species_life_form_check,
  ADD CONSTRAINT species_life_form_check
    CHECK (life_form IS NULL OR life_form IN ('tree', 'shrub', 'herb', 'vine', 'other')),
  DROP CONSTRAINT IF EXISTS species_cultivation_status_check,
  ADD CONSTRAINT species_cultivation_status_check
    CHECK (cultivation_status IS NULL OR cultivation_status IN ('wild', 'cultivated', 'mixed', 'unknown'));

ALTER TABLE public.species
  DROP CONSTRAINT IF EXISTS species_plant_uses_check,
  ADD CONSTRAINT species_plant_uses_check
    CHECK (plant_uses <@ ARRAY['fruit', 'nut', 'vegetable', 'edible']::TEXT[]);

CREATE INDEX IF NOT EXISTS idx_species_plant_uses
  ON public.species USING GIN (plant_uses)
  WHERE is_active = TRUE AND nature_topic = 'plants';

