es":["fruit","edible"],"identification_notes":"植株乔木状;茎高大;叶聚生茎顶，羽状全裂;浆果核果状，椭圆形，橙黄色。","habitat_notes":"原产于西亚地区，唐代随着西域商人传入我国。","seasonality_notes":"含糖量达70%~80%，可直接在树上变成果干，颜色变红褐色。","cover_image_url":"/fruits/images/phoenix-dactylifera-1.jpg","is_active":true},{"slug":"musa-spp","common_name":"香蕉","scientific_name":"Musa spp.","aliases":["芭蕉"],"taxon_group":"芭蕉科 芭蕉属","life_form":"herb","cultivation_status":"cultivated","plant_uses":["fruit","edible"],"identification_notes":"高大直立草本;浆果成排生长，圆柱状，黄色。","habitat_notes":"祖先是小果野蕉和野蕉，我国南方有产。","seasonality_notes":"一般七八分熟时采摘，室温下可自然成熟变软。","cover_image_url":"/fruits/images/musa-spp-1.jpg","is_active":true},{"slug":"ananas-comosus","common_name":"凤梨","scientific_name":"Ananas comosus","aliases":["菠萝","黄梨"],"taxon_group":"凤梨科 凤梨属","life_form":"herb","cultivation_status":"cultivated","plant_uses":["fruit","edible"],"identification_notes":"直立草本;叶条形，边缘常有锐齿;花紫色，下有淡红色苞片;聚花果橙黄色或绿色。","habitat_notes":"原产于美洲热带地区，约于17世纪被葡萄牙人引种到中国澳门。","seasonality_notes":"由许多果实组成的聚花果，经常在未完全成熟时被采摘催熟。","cover_image_url":"/fruits/images/ananas-comosus-1.jpg","is_active":true},{"slug":"saccharum-officinarum","common_name":"甘蔗","scientific_name":"Saccharum officinarum","aliases":[],"taxon_group":"禾本科 甘蔗属","life_form":"herb","cultivation_status":"cultivated","plant_uses":["fruit","edible"],"identification_notes":"直立草本;茎紫红色、高大;叶条形，边缘有锯齿。","habitat_notes":"原产于亚洲热带地区，只能在温暖的南方地区种植。","seasonality_notes":"秋季天凉后开始积累糖分，北京地区秋冬季节上市。","cover_image_url":"/fruits/images/saccharum-officinarum-1.jpg","is_active":true},{"slug":"ribes-spp","common_name":"醋栗","scientific_name":"Ribes spp.","aliases":["茶藨子"],"taxon_group":"茶藨子科 茶藨子属","life_form":"shrub","cultivation_status":"cultivated","plant_uses":["fruit","edible"],"identification_notes":"灌木;花黄绿色或紫红色;浆果球形，红色、乳白色或紫黑色。","habitat_notes":"喜凉怕热，在我国主要出产于东北和西北地区。","seasonality_notes":"味道很酸，有些还有涩味，不适于鲜食，一般熬制成果酱。","cover_image_url":"/fruits/images/ribes-spp-1.jpg","is_active":true},{"slug":"vitis-vinifera","common_name":"葡萄","scientific_name":"